-- Customer credit balances generated by authorized returns.
-- Run after:
--   054_independent_sales_gifts.sql

USE panaderia_db;

SET @orders_credit_redeemed_exists = (
  SELECT COUNT(*)
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'orders'
    AND COLUMN_NAME = 'credit_redeemed_amount'
);

SET @orders_credit_redeemed_sql = IF(
  @orders_credit_redeemed_exists = 0,
  'ALTER TABLE orders
     ADD COLUMN credit_redeemed_amount DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER exchange_total',
  'SELECT 1'
);

PREPARE orders_credit_redeemed_stmt FROM @orders_credit_redeemed_sql;
EXECUTE orders_credit_redeemed_stmt;
DEALLOCATE PREPARE orders_credit_redeemed_stmt;

SET @sales_returns_credit_amount_exists = (
  SELECT COUNT(*)
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'sales_returns'
    AND COLUMN_NAME = 'credit_amount'
);

SET @sales_returns_credit_amount_sql = IF(
  @sales_returns_credit_amount_exists = 0,
  'ALTER TABLE sales_returns
     ADD COLUMN credit_amount DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER notes',
  'SELECT 1'
);

PREPARE sales_returns_credit_amount_stmt FROM @sales_returns_credit_amount_sql;
EXECUTE sales_returns_credit_amount_stmt;
DEALLOCATE PREPARE sales_returns_credit_amount_stmt;

SET @sales_return_items_credit_amount_exists = (
  SELECT COUNT(*)
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'sales_return_items'
    AND COLUMN_NAME = 'credit_amount'
);

SET @sales_return_items_credit_amount_sql = IF(
  @sales_return_items_credit_amount_exists = 0,
  'ALTER TABLE sales_return_items
     ADD COLUMN credit_amount DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER returned_commercial_value',
  'SELECT 1'
);

PREPARE sales_return_items_credit_amount_stmt FROM @sales_return_items_credit_amount_sql;
EXECUTE sales_return_items_credit_amount_stmt;
DEALLOCATE PREPARE sales_return_items_credit_amount_stmt;

SET @sales_return_replacement_nullable_sql = (
  SELECT IF(
    COUNT(*) > 0,
    'ALTER TABLE sales_return_items
       DROP FOREIGN KEY fk_sales_return_items_replacement_product',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS
  WHERE CONSTRAINT_SCHEMA = DATABASE()
    AND TABLE_NAME = 'sales_return_items'
    AND CONSTRAINT_NAME = 'fk_sales_return_items_replacement_product'
);

PREPARE sales_return_replacement_nullable_stmt FROM @sales_return_replacement_nullable_sql;
EXECUTE sales_return_replacement_nullable_stmt;
DEALLOCATE PREPARE sales_return_replacement_nullable_stmt;

ALTER TABLE sales_return_items
  MODIFY COLUMN replacement_product_id BIGINT UNSIGNED NULL,
  MODIFY COLUMN replacement_commercial_value DECIMAL(12,2) NOT NULL DEFAULT 0;

SET @sales_return_replacement_fk_sql = (
  SELECT IF(
    COUNT(*) = 0,
    'ALTER TABLE sales_return_items
       ADD CONSTRAINT fk_sales_return_items_replacement_product
         FOREIGN KEY (replacement_product_id) REFERENCES products (id)
         ON DELETE RESTRICT ON UPDATE CASCADE',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS
  WHERE CONSTRAINT_SCHEMA = DATABASE()
    AND TABLE_NAME = 'sales_return_items'
    AND CONSTRAINT_NAME = 'fk_sales_return_items_replacement_product'
);

PREPARE sales_return_replacement_fk_stmt FROM @sales_return_replacement_fk_sql;
EXECUTE sales_return_replacement_fk_stmt;
DEALLOCATE PREPARE sales_return_replacement_fk_stmt;

CREATE TABLE IF NOT EXISTS customer_credit_accounts (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  customer_id BIGINT UNSIGNED NOT NULL,
  balance_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_customer_credit_account_customer (customer_id),
  CONSTRAINT fk_customer_credit_account_customer
    FOREIGN KEY (customer_id) REFERENCES customers (id)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_customer_credit_account_balance CHECK (balance_amount >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS customer_credit_ledger (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  customer_id BIGINT UNSIGNED NOT NULL,
  movement_type ENUM('generated','redeemed','adjusted') NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  balance_after DECIMAL(12,2) NOT NULL,
  sales_return_id BIGINT UNSIGNED NULL,
  order_id BIGINT UNSIGNED NULL,
  notes VARCHAR(255) NULL,
  created_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_customer_credit_ledger_customer_date (customer_id, created_at),
  KEY idx_customer_credit_ledger_return (sales_return_id),
  KEY idx_customer_credit_ledger_order (order_id),
  CONSTRAINT fk_customer_credit_ledger_customer
    FOREIGN KEY (customer_id) REFERENCES customers (id)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_customer_credit_ledger_return
    FOREIGN KEY (sales_return_id) REFERENCES sales_returns (id)
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_customer_credit_ledger_order
    FOREIGN KEY (order_id) REFERENCES orders (id)
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_customer_credit_ledger_created_by
    FOREIGN KEY (created_by) REFERENCES users (id)
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT chk_customer_credit_ledger_amount CHECK (amount > 0 AND balance_after >= 0)
) ENGINE=InnoDB;
